post_parakeet_energy = result("energy-parakeet-long-fix")
assert post_parakeet_energy["order"] == ["parakeet-v3"] and len(post_parakeet_energy["trials"]) == 1
for trial in [*energy["trials"], *post_energy["trials"], *post_parakeet_energy["trials"]]:
    power = trial["active"]["mean"]
    label = esc(trial["model"]) + (" · rejected research control" if trial["model_spec"].get("research_only") else "")
    if trial["model"] == "qwen3-asr":
        label += " · after long-file fix" if trial is post_energy["trials"][0] else " · earlier profile"
    if trial["model"] == "parakeet-v3":
        label += " · after long-file fix" if trial is post_parakeet_energy["trials"][0] else " · earlier profile"
    drift = abs(trial["idle_after"]["mean"]["total_power"] - trial["idle_before"]["mean"]["total_power"])
    increment = power["total_power"] - (trial["idle_before"]["mean"]["total_power"] + trial["idle_after"]["mean"]["total_power"]) / 2
    estimate = "Inconclusive: idle drift" if increment <= 0 or drift > abs(increment) / 2 else f'{trial["incremental_joules_per_audio_minute"]["total_power"]:.1f} J'
    energy_rows.append(f'<tr><th>{label}</th><td>{trial["requests"]}</td><td>{trial["aggregate_rtf"]:.4f}</td><td>{power["cpu_power"]:.1f} / {power["gpu_power"]:.1f} W</td><td>{power["total_power"]:.1f} W</td><td>{trial["idle_before"]["mean"]["total_power"]:.1f} → {trial["idle_after"]["mean"]["total_power"]:.1f} W</td><td>{estimate}</td></tr>')
energy_panel = '<details><summary>System power: measured sustained inference, with explicit limits.</summary><p>A rootless, version-pinned monitor sampled resident-model idle → sustained serial recognition → idle for each engine, in seeded random order. The six shipping engines and the previously rejected Cohere conversion ran on verified public speech. Interior power samples exclude three seconds around each transition. Estimated incremental joules subtract the mean of both idle blocks and normalize by decoded audio minutes.</p><div class="scroll"><table><thead><tr><th>Engine</th><th>Requests</th><th>Sustained RTF ↓</th><th>CPU / GPU mean</th><th>Total active mean</th><th>Idle before → after</th><th>Incremental estimate / input audio minute ↓</th></tr></thead><tbody>' + ''.join(energy_rows) + '</tbody></table></div><p class="small muted">OS/private-API whole-system estimates include observer and desktop activity. One block per model, sparse sampling, visibly drifting idle levels and no thermal isolation; these are exploratory throughput measurements, not calibrated app attribution, battery life or consumer-product rankings. Separate post-fix Qwen and Parakeet blocks are included; differences do not isolate code effects. The later Parakeet idle power drifted from 100.9 to 61.0 W with another render active on this shared Mac. Its estimate is inconclusive. A post-hoc diagnostic flags idle drift above half the estimated inference increment (or a nonpositive increment); this is a heuristic, not a confidence interval. The rejected conversion remains excluded from shipping regardless of its power result. <a href="../benchmarks/results/energy.json">All original filtered samples, idle blocks, outputs and fingerprints</a> · <a href="../benchmarks/results/energy-qwen-long-fix.json">Post-fix Qwen block</a> · <a href="../benchmarks/results/energy-parakeet-long-fix.json">Confounded post-fix Parakeet block</a> · <a href="../benchmarks/README.md">Method and reproduction</a>.</p></details>'
long_data = result("long-completeness")
assert set(long_data["completed_models"]) == set(long_data["expected_models"]), "Long-file experiment is incomplete"
long_rows = []
for label, run in [("Qwen · before budget reset", long_data["qwen_before"]), ("Parakeet · before direct chunks", long_data["parakeet_before"]), *long_data["models"].items()]:
    cases = {case["id"]: case for case in run["cases"]}
    short, hour = cases["public-concat-10m"], cases["public-concat-60m"]
    long_rows.append(f'<tr><th>{esc(label)}</th><td>{short["score"]["wer"]*100:.2f}%</td><td>{hour["score"]["wer"]*100:.2f}%</td><td>{hour["wall_ms"]/1000:.1f} s</td><td>{hour["peak_gpu_bytes"]/1e9:.2f} GB</td><td>{hour["output_words"]:,} / {hour["reference_words"]:,}</td></tr>')
long_panel = '<details><summary>Long-file completeness: finding and fixing a real truncation failure.</summary><p>The old Qwen route shared an 8,192-token ceiling across a file. On the hour-long fixture it returned 6,734 words against 9,032 reference words, with 26.85% WER. OSpr now cuts long Qwen input at low-energy boundaries, at most 30 seconds each, and resets a 2,048-token budget per chunk. All samples remain contiguous; no recognized words are deduplicated. Reaching a chunk budget fails rather than saving a partial transcript. Chunk times are coarse boundaries, not word alignment.</p><div class="scroll"><table><thead><tr><th>Engine / path</th><th>10-minute WER</th><th>Hour WER</th><th>Hour inference</th><th>Hour GPU allocator peak</th><th>Output / reference words</th></tr></thead><tbody>' + ''.join(long_rows) + '</tbody></table></div><p>Parakeet’s original overlap pipeline measured 12.38% hour-long WER; direct bounded chunks reduced it to 2.72%, with 482/485 existing outputs text-identical. Three natural AMI prefixes improved WER and one worsened slightly; all 1,333 returned word timestamps were bounded and ordered. Speaker DER was unchanged and remains poor. This does not isolate overlap merging from boundary/context effects. The single production timing was slower than the research candidate on this shared Mac, so no isolated timing speedup is claimed. <a href="../benchmarks/results/ami-parakeet-v3-after-long-fix.json">Natural-meeting control</a>. The hour-long Qwen result improved to 2.36% WER, 60.1 seconds and 3.88 GB allocator peak. The 10-minute case worsened from 1.18% to 1.71% WER, so smaller context has a tradeoff. Of 515 existing regression/English/multilingual outputs, 512 stayed text-identical; the three changes were clips over 30 seconds. The main 200/165 English-slice aggregate WER stayed unchanged. The earlier concatenated regression clip moved from 5.12% to 5.51% WER and 2.76% to 2.50% CER.</p><p class="small muted">One warm trial per case, synthetic joins and repeated public speech, fixed order and no thermal isolation. These test duration/resource limits; they are not natural-meeting, new-speaker or production accuracy. Repeated speech can make localized alignment ambiguous. Counts alone do not establish correct content. <a href="../benchmarks/results/long-completeness.json">Per-case metrics, original results, short-suite comparisons and fingerprints</a> · <a href="../benchmarks/fixtures/long-session.json">Exact source spans and references</a>.</p></details>'
